import{_ as i,l as r,o as e,c as s,v as t,p as l,x as n,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"强归纳与结构归纳","description":"","frontmatter":{"title":"强归纳与结构归纳","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/strong-induction.md","filePath":"cs/strong-induction.md","lastUpdated":1789023840000}'),p={name:"cs/strong-induction.md"};function E(_,a,m,P,A,u){const o=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="强归纳与结构归纳" tabindex="-1">强归纳与结构归纳 <a class="header-anchor" href="#强归纳与结构归纳" aria-label="Permalink to &quot;强归纳与结构归纳&quot;">​</a></h1><div class="epigraph"><p>有时 $P(n)$ 并不从 $P(n-1)$ 长出来，而从所有更小的实例长出来；公式和树则沿定义的构造规则推。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/mathematical-induction">数学归纳</a>钉死了 \\(P(0)\\) 与 \\(P(k)\\Rightarrow P(k+1)\\)，并点名强归纳与结构归纳，当时不展开。本课不重写自然数梯子，也不从 Peano 另起。缺口是：Fibonacci、摊还里的「拆成更小的两段」、语法树的性质，普通一步假设不够，或对象根本不是 \\(\\mathbb{N}\\) 上的下标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(F_n=F_{n-1}+F_{n-2}\\) 的证明要同时用 \\(P(n-1)\\) 与 \\(P(n-2)\\)。缺口因此不是新的 \\(P\\)，而是强归纳：要证 \\(P(n)\\)，可假设<strong>所有</strong> \\(k\\lt n\\) 已成立（基础仍覆盖最小的若干个）。它与普通归纳在 \\(\\mathbb{N}\\) 上等价，写法不同：当递推宽度大于 \\(1\\) 时，强形式更省事。</p><p>结构归纳：对象由规则生成（空树；由子树造新树；命题由原子与连接词生成）。对每条规则证：子对象有性质则对象有性质。这不是「对树高做普通归纳」的散文——必须对准定义的条款。后课<a href="/cs/loop-invariant">循环不变式</a>仍是 \\(\\mathbb{N}\\) 上的普通归纳；抽象语法是结构归纳。</p><h3 id="强假设不是免费午餐" tabindex="-1">强假设不是免费午餐 <a class="header-anchor" href="#强假设不是免费午餐" aria-label="Permalink to &quot;强假设不是免费午餐&quot;">​</a></h3><p>基础步往往要写 \\(P(0)\\) 与 \\(P(1)\\)，或所有最小构造。漏掉第二条规则（空表、空树），整棵倒掉。在归纳步里调用 \\(P(n)\\) 自身，仍是循环论证。</p><p><span class="marginnote">Rosen 把强归纳与「完全归纳」对照，并用递归定义的公式做结构归纳。后课图若无环，可沿拓扑序做归纳；有环则结构归纳的「子对象更小」先要另找良基关系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写清 \\(P(n)\\)。强归纳：固定 \\(n\\)，假设 \\(\\forall k\\lt n\\,P(k)\\)，证 \\(P(n)\\)；检查 \\(n\\) 较小时不引用不存在的前项。结构归纳：按定义分情形，每情形只引用真子结构。</p>',11)),(e(),l(h,null,{default:n(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WEAK%5B%22%E6%99%AE%E9%80%9A%EF%BC%9AP(k)%20%E2%87%92%20P(k%2B1)%22%5D%20--%3E%20STR%5B%22%E5%BC%BA%EF%BC%9A%E5%85%A8%E4%BD%93%E6%9B%B4%E5%B0%8F%22%5D%0A%20%20STR%20--%3E%20ST%5B%22%E7%BB%93%E6%9E%84%EF%BC%9A%E6%B2%BF%E6%9E%84%E9%80%A0%E8%A7%84%E5%88%99%22%5D%0A%20%20ST%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%B8%BD%E7%AC%BC%E6%98%AF%E5%AD%98%E5%9C%A8%E6%80%A7%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>递归程序的正确性：参数在某良基序上变小，对那个序做强归纳或结构归纳。后课树高、表达式求值、合式公式的唯一读法，都走结构归纳。渐近记号仍未进场：归纳证的是「对每个 \\(n\\) 成立」，不自动给出 \\(O\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入序数、超限归纳。鸽笼、容斥是后面的计数工具，不是归纳格式的替代。也不把数学归纳与自然科学的「归纳推理」混名。</p><p>后课默认：递推宽度大于 \\(1\\) 用强归纳；递归数据类型用结构归纳。存在性计数下一课才换工具。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>强归纳允许使用所有更小实例；基础要盖住递推宽度。</li><li>结构归纳对准递归定义的每条规则。</li><li>正确性归纳仍不代替代价；鸽笼是另一条存在原理。</li><li>出处：Rosen, <em>Discrete Mathematics and Its Applications</em>。</li></ul>',7))])}const b=i(p,[["render",E]]);export{f as __pageData,b as default};
